-- Read-only production readiness inspection. No migrations or activation.
select jsonb_build_object('user_profiles',to_regclass('public.user_profiles') is not null,'app_sessions',to_regclass('public.app_sessions') is not null,'audit_teams',to_regclass('public.audit_teams') is not null,'audit_team_memberships',to_regclass('public.audit_team_memberships') is not null,'pgcrypto',exists(select 1 from pg_extension where extname='pgcrypto'),'feed_schema_present',to_regclass('public.ingestion_sources') is not null,'import_schema_present',to_regclass('public.company_import_batches') is not null,'private_payments_model_bucket',exists(select 1 from storage.buckets where id='payments-primary-models' and not public),'applied_migrations',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations)) as preflight;
